const { chromium } = require('playwright-core');
(async () => {
  const exe = require('fs').readdirSync(process.env.HOME + '/Library/Caches/ms-playwright').filter(d=>d.startsWith('chromium-')).sort().pop();
  const browser = await chromium.launch({ executablePath: `${process.env.HOME}/Library/Caches/ms-playwright/${exe}/chrome-mac/Chromium.app/Contents/MacOS/Chromium` });
  const page = await browser.newPage();
  await page.goto('file:///Users/vmysla/src/ab-study/arms/calculator-rep-control-01/control/index.html');
  for (const seq of ['0.1+0.2=', '1/3=', '0.1+0.2\n', '1/3\n']) {
    await page.keyboard.press('Escape');
    for (const ch of seq) await page.keyboard.press(ch === '\n' ? 'Enter' : ch);
    console.log(JSON.stringify(seq), await page.textContent('[data-testid="calc-display"]'), '|', await page.$eval('[data-testid="tape-row"]', r=>r.innerText.replace(/\n/g,' | ')));
  }
  // in-page fuzz
  const bad = await page.evaluate(() => {
    const keys = [...document.querySelectorAll('.keys button')].filter(b => b.dataset.testid !== 'key-clear');
    const clr = document.querySelector('[data-testid="key-clear"]');
    const out = [];
    for (let t = 0; t < 20000 && out.length < 10; t++) {
      clr.click(); const seq = [];
      const n = 3 + Math.floor(Math.random()*14);
      for (let i = 0; i < n; i++) { const k = keys[Math.floor(Math.random()*keys.length)]; seq.push(k.textContent); k.click(); }
      const row = document.querySelector('[data-testid="tape-row"]');
      if (!row) continue;
      const txt = row.innerText;
      const long = (txt.match(/[\d.]+/g) || []).some(s => s.replace(/\./g,'').replace(/^0+/,'').length > 16);
      if (long || /\d{11,}/.test(row.querySelector('.tape-result').textContent)) out.push(seq.join(' ') + '  =>  ' + txt.replace(/\n/g,' | '));
      document.querySelector('[data-testid="tape-clear"]').click();
    }
    return out;
  });
  console.log(bad);
  await browser.close();
})();
EOF
